INSERT INTO `_catalog_new_pages` (`id`,`parent_id`,`caption`,`icon_image`,`min_rank`,`min_vip`,`order_num`,`page_link`,`page_layout`,`page_strings_1`,`page_strings_2`,`visible`,`enabled`) VALUES (930001,-1,'Front Page',213,1,0,1,'frontpage','frontpage4','catalog_frontpage_headline_shop_GENERAL|','<i><b><font color=\"#0E668C\" size=\"16\">What can I find in the shop?</font></b></i><br><br>Upgrade your clothing with PixelRP Club, adopt a pet or decorate your room the way you like it. Whatever you like to do most in PixelRP, you\'ll find a way to make that experience even better by browsing our Shop.<br><br><li>Join <a href=\"event:catalog/open/habbo_club\">PixelRP Club</a></li><li><a href=\"event:catalog/open/set_pixelnew\">Decorate </a>your room</li><li>Adopt a <a href=\"event:catalog/open/pets_shop\">Pet</a></li><li>Make your own <a href=\"event:catalog/open/category_wired\">Wired</a> games </li><li>Trade in our <a href=\"event:catalog/open/marketplace_offers\">Marketplace</a></li><br><i><b><font color=\"#0E668C\" size=\"16\">Where can I get credits?</font></b></i><br><br>We have a couple of methods of payment such as Credit Cards and PayPal which allow you to purchase credits at our Web Shop.<br><br><a href=\"https://pixelrp.co\" target=\"_new\">Visit our currency page for more info.</a>|Redeem a voucher code here:',b'1',b'1');
