INSERT INTO `_catalog_new_pages` (`id`,`parent_id`,`caption`,`icon_image`,`min_rank`,`min_vip`,`order_num`,`page_link`,`page_layout`,`page_strings_1`,`page_strings_2`,`visible`,`enabled`) VALUES (930004,930245,'PixelRP Club',172,1,0,3,'habbo_club','recycler_info','habboclub_2|VIP_badge','PixelRP Club is free and you get in when you start. Although you can buy VIP read more about that below.|VIP is avaliable from pixelrp.co/store/vip for $40USD\\r\\r\r\nYou get the following features with VIP:\\r\r\nPush/Pull commands, VIP Catalogue including cool rares\\r\r\nand heaps of cool other features. So why not get it now?\\r',b'1',b'0');
INSERT INTO `_catalog_new_pages` (`id`,`parent_id`,`caption`,`icon_image`,`min_rank`,`min_vip`,`order_num`,`page_link`,`page_layout`,`page_strings_1`,`page_strings_2`,`visible`,`enabled`) VALUES (930005,930245,'Silver VIP',196,1,1,30,'','default_3x3','vipheader1|vipteaser2','Thank you for purchasing VIP! This section of the catalogue is especially for our VIP users. The Rares in this section aren\'t cheap, but you can sell them on to non VIP members for a much heftier price!|Click on an item for more information.',b'1',b'1');
INSERT INTO `_catalog_new_pages` (`id`,`parent_id`,`caption`,`icon_image`,`min_rank`,`min_vip`,`order_num`,`page_link`,`page_layout`,`page_strings_1`,`page_strings_2`,`visible`,`enabled`) VALUES (930006,930004,'Buy Club',75,1,0,3,'','default_3x3','habboclub|catalog_hc_teaser','PixelRP club comes with many bonuses! More hair and clothes choices, more hair and clothes colours to come from, new room layouts, new dances, and much, much more!|',b'0',b'0');
