INSERT INTO `_catalog_new_pages` (`id`,`parent_id`,`caption`,`icon_image`,`min_rank`,`min_vip`,`order_num`,`page_link`,`page_layout`,`page_strings_1`,`page_strings_2`,`visible`,`enabled`) VALUES (930008,930245,'Marketplace',69,1,0,27,'','pets3','catalog_marketplace_header_en|catalog_note_marketplace','The PixelRP Marketplace is a convenient and safe way to buy and sell items in PixelRP.|How does the PixelRP Marketplace work?|Selling items: You can sell any item which is tradable by selecting the item in your inventory and clicking on \"Sell in Marketplace\". You can also use items currently in the shop.\r\n\r\nBuying items: Browse for the item you want to buy on the Marketplace Offers page and click Buy. We guarantee you\'ll get the item at the cheapest price available at the moment of purchase.|',b'0',b'0');
