INSERT INTO `_catalog_new_pages` (`id`,`parent_id`,`caption`,`icon_image`,`min_rank`,`min_vip`,`order_num`,`page_link`,`page_layout`,`page_strings_1`,`page_strings_2`,`visible`,`enabled`) VALUES (930012,-1,'Pet Shop',8,1,0,3,'pets_shop','pets3','catalog_pet_headline1|ctlg_pet_note','Pets are inhabitants of Habbo Hotel too so each pet owner needs to know a bit about them. If you want to look after your pet properly, make sure you read the following points carefully.|A few things you should know:|*You can place a pet in your room or take one for a walk with you in other rooms.\r\n*You can\'t trade your pet but they can follow you to friend\'s rooms to gather scratches.\r\n*You can have up to 50 pets in your room, but look after them all!\r\n\r\n\r\n*Look after your pet with food, water and treats. Check the Pets\' Accessories.\r\n*Unlock Badges and Achievements by Training your Pet.|Click your Pet and hit the \"Train\" button to get a list of commands that will level up your Pet in no time!',b'1',b'1');
