INSERT INTO `_catalog_new_pages` (`id`,`parent_id`,`caption`,`icon_image`,`min_rank`,`min_vip`,`order_num`,`page_link`,`page_layout`,`page_strings_1`,`page_strings_2`,`visible`,`enabled`) VALUES (930026,930175,'Pura',48,1,0,176,'','default_3x3','puraheader|catalog_pura_teaser1','The cleanest, freshest range. You can almost hear it breathe cool and tranquility within your room. Use it to create a haven away from the hectic lifestyle of PixelRP Hotel.|',b'1',b'1');
