INSERT INTO `_catalog_new_pages` (`id`,`parent_id`,`caption`,`icon_image`,`min_rank`,`min_vip`,`order_num`,`page_link`,`page_layout`,`page_strings_1`,`page_strings_2`,`visible`,`enabled`) VALUES (930041,930175,'Health Spa',211,1,0,112,'','default_3x3','catalog_header_spa|catalog_teaser_spa','A day at the spa! Inhale...Exhale...Inhale...Exhale. With all the features of a premium Spa, you can now create your very own PixelRP Health Spa relaxing retreat! Robe and slippers not included.',b'1',b'1');
