INSERT INTO `_catalog_new_pages` (`id`,`parent_id`,`caption`,`icon_image`,`min_rank`,`min_vip`,`order_num`,`page_link`,`page_layout`,`page_strings_1`,`page_strings_2`,`visible`,`enabled`) VALUES (930043,930245,'Duckets Shop',178,1,0,13,'','info_duckets','duckets_header|','<i><b><font color=\"#591d97\" size=\"16\">What are Duckets?</font></b></i><br><br>Ducket is a free virtual currency you can earn daily just by playing Habbo.<br><br><i><b><font color=\"#591d97\" size=\"16\">What are they good for?</font></b></i><br><br><li><a href=\"event:catalog/open/rentables_spaces\">Paint</a>  your rooms.</li><li>Get a <a href=\"event:catalog/open/duckets_cat\">cat</a> and <a href=\"event:catalog/open/duckets_petaccessories\">accessories</a>.</li><li><a href=\"event:catalog/open/rentables_info\">Rent furniture</a>.</li><li>Get <a href=\"event:catalog/open/special_effects\">avatar effects</a>.</li><li>Whatever fun stuff we come up with.</li><br><i><b><font color=\"#591d97\" size=\"16\">How can I get them?</font></b></i><br><br><li>Visit Habbo! Get some every day. The more active you are, the more you\'ll earn.</li><li>You get some for each completed achievement in the <a href=\"event:talent/open/citizenship\">Citizenship track</a>.</li><li>Any other surprise we might come up with!</li>|',b'1',b'1');
