INSERT INTO `_catalog_new_pages` (`id`,`parent_id`,`caption`,`icon_image`,`min_rank`,`min_vip`,`order_num`,`page_link`,`page_layout`,`page_strings_1`,`page_strings_2`,`visible`,`enabled`) VALUES (930237,930175,'Halloween 2015',262,1,0,4,'','default_3x3','catalog_header_hw15|catalog_teaser_hw15','Darkness and evil is spreading through the hotel and you\'re one of the ONLY Habbos that can fight the bad energy! Dodge Evil Frank, avoid dark shadowy places and make it your mission to save PixelRP Hotel from complete and TOTAL annihilation!',b'1',b'1');
INSERT INTO `_catalog_new_pages` (`id`,`parent_id`,`caption`,`icon_image`,`min_rank`,`min_vip`,`order_num`,`page_link`,`page_layout`,`page_strings_1`,`page_strings_2`,`visible`,`enabled`) VALUES (930238,930237,'Clothing',262,1,0,1,'','default_3x3','catalog_header_hw15|catalog_teaser_hw15|hween15_clothing','Does your loyalty belong to the Light Guardians? Or are you intent on corrupting and destroying PixelRP Hotel with the Lost Souls? Whichever side you choose, you can dress the part with these spooktacular PixelRP Couture outfits. Which side will you choose?',b'1',b'1');
